struct bst_test_case {
    const char* name;
    void (*fn)();
};

inline std::vector<bst_test_case>& bst_tests()
{
    static std::vector<bst_test_case> tests;
    return tests;
}

struct bst_registrar {
    bst_registrar(const char* name, void (*fn)())
    {
        bst_tests().push_back({name, fn});
    }
};

#define BST_CAT_IMPL(a, b) a##b
