    static bst_registrar BST_CAT(bst_test_reg_, __LINE__)(name, &BST_CAT(bst_test_fn_, __LINE__)); \
    static void BST_CAT(bst_test_fn_, __LINE__)()
#define REQUIRE(expr) \
    do { \
        if (!(expr)) { \
            throw std::runtime_error(std::string("REQUIRE failed: ") + #expr + " at line " + std::to_string(__LINE__)); \
        } \
    } while (false)

inline int bst_run_all_tests()
{
    int failed = 0;
    for (const auto& test : bst_tests()) {
        try {
            test.fn();
            std::cout << "PASS: " << test.name << '\n';
        } catch (const std::exception& e) {
            std::cerr << "FAIL: " << test.name << ": " << e.what() << '\n';
            ++failed;
        }
    }
    std::cout << bst_tests().size() - failed << "/" << bst_tests().size() << " tests passed\n";
    return failed == 0 ? 0 : 1;
}

